INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3901, 'Numbers 16:37', 'Numbers', 16, 37, '&nbsp;”د هارون اِمام زوئ اِلى‌عزر ته ووايه چې کوم سړى سوزېدلى دى چې د هغوئ د اور لوښى لرې کړى او هغه سکارۀ دې د اور لوښو نه لږ لرې وولى، ځکه چې د اور لوښى مقدس دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3902, 'Numbers 16:38', 'Numbers', 16, 38, '&nbsp;کله چې دا لوښى د مالِک خُدائ په قربان‌ګاه باندې پېش کېدل نو مقدس شول. نو د دې سړو د اور لوښى واخله کوم چې د خپلې ګناه په وجه مړۀ شوى دى، وې ټکوه نرى نرى پترى شان ترې نه جوړ کړه او د قربان‌ګاه پټولو دپاره سر ترې نه جوړ کړه. دا به د بنى اِسرائيلو دپاره د خبردارۍ يوه نښه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3903, 'Numbers 16:39', 'Numbers', 16, 39, '&nbsp;نو اِلى‌عزر اِمام د اور لوښى واخستل او د ټکولو دپاره يې ورکړل، د قربان‌ګاه د پټولو د سر دپاره نرى نرى پترى ترې نه جوړ کړے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3904, 'Numbers 16:40', 'Numbers', 16, 40, '&nbsp;دا د بنى اِسرائيلو دپاره يو خبردارے وو چې څوک د هارون اولاد نۀ وى نو بل غېر سړے به قربان‌ګاه ته نزدې نۀ راځى د دې دپاره چې مالِک خُدائ ته خوشبوئى وسوزوى. ګنې هغه به د قورح او د هغۀ د سړو په شان تباه شى. دا هر څۀ هم هغه شان وشول چې څنګه مالِک خُدائ اِلى‌عزر له د موسىٰ په ذريعه حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3905, 'Numbers 16:41', 'Numbers', 16, 41, '&nbsp;خو په ورپسې ورځ ټول قوم موسىٰ او هارون ته وغورېدو او وې وئيل، ”تاسو د مالِک خُدائ خلق وژلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3906, 'Numbers 16:42', 'Numbers', 16, 42, '&nbsp;د هغې نه پس کله چې هغوئ ټول د موسىٰ او هارون خِلاف راغونډ شوى وُو، چې هغوئ د خېمې طرف ته وکتل نو وې ليدل چې وريځې خېمه پټه کړې وه او د مالِک خُدائ د حضور جلال راڅرګند شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3907, 'Numbers 16:43', 'Numbers', 16, 43, '&nbsp;موسىٰ او هارون لاړل او د خېمې په مخکښې ودرېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3908, 'Numbers 16:44', 'Numbers', 16, 44, '&nbsp;او مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3909, 'Numbers 16:45', 'Numbers', 16, 45, '&nbsp;”د دې خلقو نه لرې شه او زۀ سمدستى هغوئ تباه کوم.“ خو موسىٰ او هارون پړمخې پرېوتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3910, 'Numbers 16:46', 'Numbers', 16, 46, '&nbsp;او موسىٰ هارون ته وفرمائيل، ”خپل مجمر واخله، د قربان‌ګاه نه په کښې ژوندى سکارۀ واچوه او په سکارو باندې لږه خوشبوئى واچوه. بيا خلقو له په منډه لاړ شه او د هغوئ دپاره کفاره ادا کړه. زر شه. مالِک خُدائ په قهر دے او تباهى د مخکښې نه شروع شوې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3911, 'Numbers 16:47', 'Numbers', 16, 47, '&nbsp;هارون ته چې څنګه وئيلے شوى وُو هم هغه شان يې وکړل، خپل د اور لوښے يې واخستلو او د راغونډو خلقو مينځ ته يې ورمنډه کړه. کله چې هغۀ وليدل چې تباهى شروع وه، نو هغۀ خوشبوئى په سکارو واچوله او د خلقو دپاره يې کفاره ادا کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3912, 'Numbers 16:48', 'Numbers', 16, 48, '&nbsp;هغه د مړو او ژوندو په مينځ کښې ودرېدلو او تباهى بس شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3913, 'Numbers 16:49', 'Numbers', 16, 49, '&nbsp;کوم خلق چې مړۀ شول هغوئ په شمېر کښې څوارلس زره او اووۀ سوه کسان وُو، دا د هغې نه علاوه وُو کوم چې د قورح په سرکشۍ کښې مړۀ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3914, 'Numbers 16:50', 'Numbers', 16, 50, '&nbsp;کله چې تباهى بس شوه، نو هارون د خېمې د دروازې په خولۀ کښې موسىٰ ته راواپس شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3915, 'Numbers 17:1', 'Numbers', 17, 1, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3916, 'Numbers 17:2', 'Numbers', 17, 2, '&nbsp;”بنى اِسرائيلو ته ووايه چې تا له دولس امساګانې درکړى چې د هرې قبيلې د مشر نه يوه يوه وى. د هر سړى نوم د هغۀ په امسا باندې وليکه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3917, 'Numbers 17:3', 'Numbers', 17, 3, '&nbsp;او په يوه امسا باندې د هارون نوم وليکه چې کومه د ليوى قبيلې دپاره وى، د هرې قبيلې د مشر دپاره به يوه يوه امسا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3918, 'Numbers 17:4', 'Numbers', 17, 4, '&nbsp;دا امساګانې زما د حضور خېمې ته يوسه او د لوظ صندوق په مخکښې يې کېږده، چرته چې زۀ تا سره مِلاوېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3919, 'Numbers 17:5', 'Numbers', 17, 5, '&nbsp;بيا چې ما کوم سړے خوښ کړے وى نو د هغۀ امسا به زرغونه شى او زۀ به ستا خِلاف د بنى اِسرائيلو دا هر وخت غورېدل بند کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3920, 'Numbers 17:6', 'Numbers', 17, 6, '&nbsp;نو موسىٰ بنى اِسرائيلو ته وفرمائيل چې داسې وکړئ او د هغوئ هر يو مشر هغۀ له يوه امسا ورکړه، چې د هرې قبيلې دپاره يوه يوه وه، دا ټولې دولس وې او په دې دولسو امساګانو کښې يوه امسا د هارون وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3921, 'Numbers 17:7', 'Numbers', 17, 7, '&nbsp;بيا موسىٰ هغه ټولې امساګانې په خېمه کښې د مالِک خُدائ د لوظ صندوق په مخکښې کېښودې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3922, 'Numbers 17:8', 'Numbers', 17, 8, '&nbsp;په ورپسې ورځ، کله چې موسىٰ خېمې ته دننه لاړو، نو هغۀ د هارون امسا وليده چې د ليوى قبيلې دپاره وه، هغه زرغونه شوې وه، دې غوټۍ او ګلونه کړى وُو او پاخۀ بادام يې نيولى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3923, 'Numbers 17:9', 'Numbers', 17, 9, '&nbsp;موسىٰ ټولې امساګانې يوړې او بنى اِسرائيلو ته يې وښودلې، هغوئ ورته وکتل او هر يو مشر خپله امسا واپس واخستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3924, 'Numbers 17:10', 'Numbers', 17, 10, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”د هارون امسا واپس د لوظ صندوق په مخکښې کېږده. باغيانو بنى اِسرائيلو ته به دا د نښې په توګه کېښودلے شى، کۀ د هغوئ غورېدل بند نۀ شى نو هغوئ به مړۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3925, 'Numbers 17:11', 'Numbers', 17, 11, '&nbsp;موسىٰ هم هغه شان وکړل چې څنګه مالِک خُدائ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3926, 'Numbers 17:12', 'Numbers', 17, 12, '&nbsp;بنى اِسرائيلو موسىٰ ته وفرمائيل، ”مونږ برباد يُو، تباه يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3927, 'Numbers 17:13', 'Numbers', 17, 13, '&nbsp;چې څوک هم د مالِک خُدائ خېمې ته نزدې ورشى، نو هغه به مړ شى، نو مونږ خو ټول مرګِ حال يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3928, 'Numbers 18:1', 'Numbers', 18, 1, '&nbsp;مالِک خُدائ هارون ته وفرمائيل، ”تا ته، ستا زامنو او ليويانو ته به خامخا د خپلو هغه بدو سزا مِلاو شى چې د هغه جرم تعلق زما د حضور خېمې د خِدمت سره وى، خو د اِمامت په خِدمت کښې د څۀ ګناه سزا به صِرف تا او ستا زامنو ته ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3929, 'Numbers 18:2', 'Numbers', 18, 2, '&nbsp;د ليوى قبيلې خپل خپلوان هم د ځان سره راوله، چې تا سره په کار کښې مدد وکړى، په هغه وخت کښې چې تۀ او ستا زامن په خېمه کښې خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3930, 'Numbers 18:3', 'Numbers', 18, 3, '&nbsp;هغوئ به ستا او د خېمې دپاره خپلې ذمه وارۍ پوره کوى، خو هغوئ دې په مقدس ځائ کښې مقدس سامان او قربان ګاه ته نۀ ور نزدې کيږى. کۀ هغوئ داسې وکړل، نو تۀ او هغوئ به ووژلے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3931, 'Numbers 18:4', 'Numbers', 18, 4, '&nbsp;هغوئ به تا سره کار کوى او په خېمه کښې به د خِدمت خپلې ټولې ذمه وارۍ پوره کوى، خو چې چا ته اجازت نۀ وى نو هغه کس به تا سره خِدمت نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3932, 'Numbers 18:5', 'Numbers', 18, 5, '&nbsp;يواځې تۀ او ستا زامن به د مقدس ځائ او د قربان‌ګاه ذمه وارۍ پوره کوئ، نو داسې به زۀ بيا بنى اِسرائيلو ته نۀ په قهر کېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3933, 'Numbers 18:6', 'Numbers', 18, 6, '&nbsp;زۀ هغه څوک يم چا چې ستا خپلوان ليويان ستا دپاره د يوې تُحفې په توګه د بنى اِسرائيلو نه خوښ کړى دى. هغوئ ما ته وقف دى، چې هغوئ په خېمه کښې خپلې ذمه وارۍ تر سره کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3934, 'Numbers 18:7', 'Numbers', 18, 7, '&nbsp;خو يواځې تۀ او ستا زامن به د اِمامت هغه ذمه وارۍ پوره کوئ کومې چې د قربان‌ګاه او د زيات مقدس ځائ سره تعلق لرى. دا ستاسو ذمه وارۍ دى، ځکه چې ما تاسو له د اِمامت تُحفه درکړې ده. هر څوک چې حقدار نۀ وى او نزدې راشى نو هغه به ووژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3935, 'Numbers 18:8', 'Numbers', 18, 8, '&nbsp;مالِک خُدائ هارون ته وفرمائيل، ”ګوره، زۀ تا له زما ټولې خاص برخې درکوم چې د نذرانو په توګه دې نۀ شى سوزولے. دا زۀ تا او ستا اولاد له درکوم چې د همېشه دپاره ستاسو په حواله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3936, 'Numbers 18:9', 'Numbers', 18, 9, '&nbsp;ډېرې مقدسې نذرانې کومې چې په قربان‌ګاه نۀ سوزولے کيږى، هغه ستاسو دى، د غلې نذرانې، د ګناه نذرانې، د ګناه د تاوان نذرانې. هر هغه څيز چې ما ته د مقدسې نذرانې په توګه پېش کيږى هغه ستا او ستا د زامنو دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3937, 'Numbers 18:10', 'Numbers', 18, 10, '&nbsp;تاسو به خامخا دا څيزونه په يو مقدس ځائ کښې خورئ او صِرف نران دا خوړلے شى، دا مقدس وګڼئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3938, 'Numbers 18:11', 'Numbers', 18, 11, '&nbsp;د دې نه علاوه، اِسرائيليان چې نورې خاص برخې ما ته پېش کوى هغه به ستاسو وى. زۀ دا د راتلونکى ټولو وختونو دپاره تا، ستا زامنو او ستا لوڼو له ورکوم. ستا د خاندان هر يو کس چې پاک وى نو هغه دا خوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3939, 'Numbers 18:12', 'Numbers', 18, 12, '&nbsp;زۀ د وړومبى پېداوار بِهترينه حِصه تاسو له درکوم کومه چې اِسرائيليان ما ته هر کال پېش کوى لکه د زيتُونو تېل، مے او غله دانه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3940, 'Numbers 18:13', 'Numbers', 18, 13, '&nbsp;دا هر څۀ ستاسو دى. د ستاسو د خاندان هر يو کس چې پاک وى نو هغه يې خوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3941, 'Numbers 18:14', 'Numbers', 18, 14, '&nbsp;د بنى اِسرائيلو په مُلک کښې چې هر څيز ما ته بغېر د څۀ شرط نه وقف شوے وى نو هغه به ستاسو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3942, 'Numbers 18:15', 'Numbers', 18, 15, '&nbsp;هر يو وړومبے پېدا شوے ماشوم يا ځناور چې اِسرائيليان يې ما ته پېش کوى هغه به ستاسو وى. خو تاسو به خامخا هر وړومبے پېدا شوے ماشوم واپس اخلئ او هر وړومبے پېدا شوے ځناور به هم واپس اخلئ کوم چې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3943, 'Numbers 18:16', 'Numbers', 18, 16, '&nbsp;چې ماشومان د يوې مياشتې شى نو هغوئ به په مقرر شوى قيمت يعنې په پينځو د سپينو زرو سيکو باندې واپس اخستلے شى، دا به د منلے شوى معيار په مطابق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3944, 'Numbers 18:17', 'Numbers', 18, 17, '&nbsp;خو د غواګانو، ګډو او چېلو وړومبے پېدا شوے بچے به واپس نۀ شى اخستلے، دا به په پوره توګه زما وى او دا به قربانيږى. وينه يې په قربان‌ګاه باندې وشيندئ او وازګه يې په اور تيارېدونکې نذرانې په توګه وسوزوئ، د دې خوشبو په ما باندې ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3945, 'Numbers 18:18', 'Numbers', 18, 18, '&nbsp;د دې غوښه ستاسو ده، لکه د دې سينه او د خاص نذرانې وروستنۍ پښه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3946, 'Numbers 18:19', 'Numbers', 18, 19, '&nbsp;کومې خاص برخې چې اِسرائيليان ما ته پېش کوى هغه زۀ په راتلونکى ټولو وختونو کښې تا، ستا زامنو او ستا لوڼو له ورکوم، دا يو نۀ ماتېدونکے لوظ دے چې ما تا او ستا اولاد سره وکړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3947, 'Numbers 18:20', 'Numbers', 18, 20, '&nbsp;مالِک خُدائ هارون ته وفرمائيل، ”تا ته به هيڅ جائيداد نۀ ملاويږى چې ستا ميراث شى او د بنى اِسرائيلو د مُلک هيڅ حِصه به تا ته نۀ حواله کيږى. زۀ مالِک خُدائ، ستا دپاره کافى يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3948, 'Numbers 18:21', 'Numbers', 18, 21, '&nbsp;مالِک خُدائ وفرمائيل، ”ما ليويانو له هره لسمه حِصه ورکړې ده کومه چې اِسرائيليان ما ته پېش کوى. دا د هغوئ دپاره زما د حضور د خېمې د خِدمت کولو مزدورى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3949, 'Numbers 18:22', 'Numbers', 18, 22, '&nbsp;نور به اِسرائيليان خېمې ته نۀ نزدې کيږى ګنې هغوئ به ځان له په خپله د مرګ سزا ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3950, 'Numbers 18:23', 'Numbers', 18, 23, '&nbsp;صِرف ليويان به د خېمې خيال ساتى او د دې پوره ذمه وارى به تر سره کوى. دا قانون به د همېشه دپاره ستاسو د اولاد دپاره هم وى. د بنى اِسرائيلو په مُلک کښې به ليويانو ته هيڅ زمکه نۀ ملاويږى چې خپله يې شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3951, 'Numbers 18:24', 'Numbers', 18, 24, '&nbsp;ځکه چې ما هغوئ له لسمه حِصه ورکړې ده کومه چې اِسرائيليان ما ته د خاص برخې په توګه پېش کوى. نو دا ځکه ما هغوئ ته وفرمائيل چې د بنى اِسرائيلو په مُلک کښې به د هغوئ جائيداد نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3952, 'Numbers 18:25', 'Numbers', 18, 25, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3953, 'Numbers 18:26', 'Numbers', 18, 26, '&nbsp;چې ليويانو ته ووايه، ”کله چې تاسو د بنى اِسرائيلو نه لسمه حِصه اخلئ کومه چې مالِک خُدائ تاسو له درکوى، نو تاسو به د دې لسمه حِصه مالِک خُدائ ته د خاص برخې په توګه پېش کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3954, 'Numbers 18:27', 'Numbers', 18, 27, '&nbsp;دا خاص برخه به د هغې نذرانې برابره ګڼلے شى کومه نذرانه چې زميندار د نوى فصل او د انګورو د لنګرۍ نه د نوؤ شرابو نه پېش کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3955, 'Numbers 18:28', 'Numbers', 18, 28, '&nbsp;نو تاسو به مالِک خُدائ ته يوه خاص برخه هم پېش کوئ کومه چې تاسو د بنى اِسرائيلو د لسمې حِصې نه اخلئ. دا برخه به تاسو د مالِک خُدائ دپاره هارون اِمام له ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3956, 'Numbers 18:29', 'Numbers', 18, 29, '&nbsp;چې څۀ تاسو ته ملاويږى نو د هغې د ټولو نه ښۀ حِصه مالِک خُدائ له ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3957, 'Numbers 18:30', 'Numbers', 18, 30, '&nbsp;نو هم داسې ليويانو ته دا اصُول وښايه. کله چې تاسو ښۀ حِصه د نذرانې په توګه پېش کوئ نو دا به تاسو دپاره داسې حساب شى لکه چې تاسو يې د خپل درمند يا د انګورو لنګرۍ نه ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3958, 'Numbers 18:31', 'Numbers', 18, 31, '&nbsp;تاسو او ستاسو خاندان هغه پاتې شوې برخه په هر ځائ کښې خوړلے شئ، ځکه چې دا ستاسو د مقدسې خېمې د خِدمت مزدورى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3959, 'Numbers 18:32', 'Numbers', 18, 32, '&nbsp;کۀ چرې تاسو د دې ښۀ حِصه مالِک خُدائ ته پېش کړى وى او بيا تاسو دا خورئ نو تاسو ته به سزا نۀ ملاويږى. هغه تحفې او قربانيانې چې قوم يې راوړى لازمى ده چې مقدسې پاتې شى خو کۀ د دې د پېش کولو نه مخکښې تاسو دې نه کومه برخه وخوړه نو وبه وژلے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3960, 'Numbers 19:1', 'Numbers', 19, 1, '&nbsp;مالِک خُدائ موسىٰ او هارون ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3961, 'Numbers 19:2', 'Numbers', 19, 2, '&nbsp;”بنى اِسرائيلو ته دا اصُول وښايئ، چې هغوئ تاسو له يوه سره غوا راولى چې لنګتون يې نۀ وى کړے او هيڅ عېب په کښې نۀ وى او يوې ورباندې هيڅکله هم نۀ وى شوې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3962, 'Numbers 19:3', 'Numbers', 19, 3, '&nbsp;او هغوئ به هغه بيا اِلى‌عزر اِمام له ورکړى. هغه به د خېمو نه بهر بوتلے شى او د هغۀ په مخکښې به حلاله کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3963, 'Numbers 19:4', 'Numbers', 19, 4, '&nbsp;اِلى‌عزر به بيا د هغې څۀ وينه واخلى او د خپلې ګوتې سره به اووۀ ځلې وينه خېمې ته مخامخ وشيندى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3964, 'Numbers 19:5', 'Numbers', 19, 5, '&nbsp;ټوله غوا، سره د څرمنې، غوښې، وينې او کولمو، به د اِمام په مخکښې وسوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3965, 'Numbers 19:6', 'Numbers', 19, 6, '&nbsp;بيا به هغه د دِيار لرګے، څۀ وېلنى او يو سور تار راوړى او دا به په اور کښې واچوى چرته چې غوا سوزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3966, 'Numbers 19:7', 'Numbers', 19, 7, '&nbsp;د هغې نه پس، هغه به خپلې جامې ووينځى او غسل به وکړى، نو بيا هغه خېمو ته دننه راتلے شى، خو تر ماښامه پورې به ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3967, 'Numbers 19:8', 'Numbers', 19, 8, '&nbsp;چا چې غوا سوزولې وى نو هغه به خامخا خپلې جامې ووينځى او غسل به وکړى، خو هغه به هم تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3968, 'Numbers 19:9', 'Numbers', 19, 9, '&nbsp;بيا هغه سړے کوم چې پاک وى هغه به د غوا ايرې راغونډې کړى او د خېمو نه بهر په يو پاک ځائ کښې به يې کېږدى، هلته به دا ايرې د بنى اِسرائيلو د قوم دپاره ساتلے شى چې د ناپاکۍ د لرې کولو اوبو تيارولو دپاره به استعماليږى. دا رسم به د ګناه د لرې کولو دپاره ادا کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3969, 'Numbers 19:10', 'Numbers', 19, 10, '&nbsp;چا چې ايرې راټولې کړې وى هغه به خامخا خپلې جامې وينځى او تر ماښامه پورې به ناپاک وى. دا اصُول د راتلونکى ټولو وختونو دپاره دى، دا به د بنى اِسرائيلو او د پردى مُلک د خلقو دپاره وى چې د هغوئ سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3970, 'Numbers 19:11', 'Numbers', 19, 11, '&nbsp;هر څوک چې د مړى سره ولګى نو هغه به اووۀ ورځې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3971, 'Numbers 19:12', 'Numbers', 19, 12, '&nbsp;هغه به خامخا په درېمه ورځ او په اوومه ورځ خپل ځان د پاکوالى په اوبو باندې پاک کړى، نو هغه به پاک شى. خو کۀ هغه په درېمه ورځ او په اوومه ورځ باندې خپل ځان پاک نۀ کړى، نو هغه به پاک نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3972, 'Numbers 19:13', 'Numbers', 19, 13, '&nbsp;هر څوک چې د مړى سره ولګى او خپل ځان پاک نۀ کړى نو هغه به ناپاک وى، ځکه چې په هغۀ باندې د پاکوالى اوبۀ نۀ دى شيندلے شوې. هغه د مالِک خُدائ د خېمې سپکاوے کوى او هغه به نور د خُدائ پاک د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3973, 'Numbers 19:14', 'Numbers', 19, 14, '&nbsp;کۀ يو سړے په خېمه کښې مړ شى، هر څوک چې د هغۀ د مرګ په وخت په خېمه کښې وى يا ورننوځى نو هغه به اووۀ ورځې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3974, 'Numbers 19:15', 'Numbers', 19, 15, '&nbsp;په خېمه کښې هر لوښے چې سر ورباندې نۀ وى هغه به هم ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3975, 'Numbers 19:16', 'Numbers', 19, 16, '&nbsp;کۀ څوک داسې کس له ګوتې وروړى چې قتل شوے وى يا د کور نه بهر په خپل مرګ مړ وى يا کۀ څوک د بنى آدم هډُوکى يا قبر له ګوتې وروړى، نو هغه به اووۀ ورځې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3976, 'Numbers 19:17', 'Numbers', 19, 17, '&nbsp;کومه غوا چې د ګناه د لرې کولو دپاره سوزولے شوې وه د هغې نه لږې ايرې به د ناپاکۍ لرې کولو دپاره واخستلے شى او په يو لوښى کښې به واچولے شى او روانې اوبۀ په کښې واچوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3977, 'Numbers 19:18', 'Numbers', 19, 18, '&nbsp;يو پاک سړے به وېلنے واخلى، په اوبو کښې به يې ډُوب کړى او اوبۀ به په خېمه، د هغې په ټول سامان او په هغه خلقو وشيندى چې کوم هلته وى او په هغه سړى باندې به اوبۀ وشيندى کوم چې د بنى آدم هډُوکى، مړى، يا قبر له ګوتې وروړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3978, 'Numbers 19:19', 'Numbers', 19, 19, '&nbsp;پاک سړے به په ناپاک سړى باندې په درېمه او په اوومه ورځ باندې اوبۀ وشيندى. او په اوومه ورځ به هغه ناپاک سړے پاک کړى، د نمرپرېواتو په وخت د خپلو جامو وينځلو او په ځان اوبۀ اچولو نه پس به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3979, 'Numbers 19:20', 'Numbers', 19, 20, '&nbsp;هر څوک چې ناپاک شوے وى او خپل ځان پاک نۀ کړى نو هغه به ناپاک پاتې شى، ځکه چې په هغۀ باندې د پاکوالى اوبۀ نۀ دى شيندلے شوې. هغه د مالِک خُدائ د خېمې سپکاوے کوى او نور به د خُدائ پاک د خلقو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3980, 'Numbers 19:21', 'Numbers', 19, 21, '&nbsp;تاسو به دا اصُول په راتلونکى ټولو وختونو کښې منئ. کوم کس چې د پاکوالى اوبۀ شيندى نو هغه به هم خامخا خپلې جامې وينځى، هر څوک چې دې اوبو له ګوتې وروړى نو هغه به تر ماښامه پورې ناپاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3981, 'Numbers 19:22', 'Numbers', 19, 22, '&nbsp;يو ناپاک کس چې څۀ څيز له هم ګوتې وروړى نو هغه به ناپاک وى او نور هر څوک چې هغه څيز له ګوتې وروړى نو هغه به هم تر ماښامه پورې ناپاک وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3982, 'Numbers 20:1', 'Numbers', 20, 1, '&nbsp;په وړومبۍ مياشت کښې د اِسرائيلو ټول قوم د صين صحرا ته راغلو او په قادِس کښې يې خېمې ولګولې. مريم هلته مړه شوه او دفن شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3983, 'Numbers 20:2', 'Numbers', 20, 2, '&nbsp;چرته چې هغوئ خېمې لګولې وې هلته اوبۀ نۀ وې، نو خلق په موسىٰ او هارون باندې راغونډ شول', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3984, 'Numbers 20:3', 'Numbers', 20, 3, '&nbsp;او هغوئ وغورېدل چې، ”دا به ښۀ وے چې مونږ د خپلو بنى اِسرائيلو سره د مالِک خُدائ د خېمې په مخکښې مړۀ شوى وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3985, 'Numbers 20:4', 'Numbers', 20, 4, '&nbsp;تاسو مونږ دې صحرا ته د دې دپاره راوستلى يُو چې دلته د خپلو څاروو سره مړۀ شُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3986, 'Numbers 20:5', 'Numbers', 20, 5, '&nbsp;تاسو مونږ ولې د مِصر نه راوويستلو او دې خراب ځائ ته مو راوستلو چې دلته هيڅ هم نۀ کيږى؟ نۀ غله دانه، نۀ اينځر، نۀ انګور او نۀ انار شته. د څښلو اوبۀ هم نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3987, 'Numbers 20:6', 'Numbers', 20, 6, '&nbsp;موسىٰ او هارون د خلقو نه لرې لاړل او د خېمې د دروازې په خولۀ کښې ودرېدل. هغوئ پړمخې د عبادت دپاره پرېوتل او د مالِک خُدائ د حضور جلال هغوئ ته راڅرګند شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3988, 'Numbers 20:7', 'Numbers', 20, 7, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3989, 'Numbers 20:8', 'Numbers', 20, 8, '&nbsp;”هغه امسا واخله چې کومه د لوظ صندوق مخې ته ده او بيا تۀ او هارون ټول قوم راغونډ کړئ. هلته د هغوئ ټولو په مخکښې هغه ګټ ته ووايه او د هغې نه به اوبۀ راوځى. نو داسې تۀ به د خلقو دپاره د ګټ نه اوبۀ راوباسې او هغوئ او د هغوئ ځناور به يې وڅښى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3990, 'Numbers 20:9', 'Numbers', 20, 9, '&nbsp;موسىٰ لاړو او امسا يې راواخستله، چې څنګه مالِک خُدائ حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3991, 'Numbers 20:10', 'Numbers', 20, 10, '&nbsp;موسىٰ او هارون د ګټ په مخکښې ټول قوم راغونډ کړو او موسىٰ وفرمائيل، ”اے باغيانو واورئ. ولې مونږ ستاسو دپاره د دې ګټ نه اوبۀ راوباسو څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3992, 'Numbers 20:11', 'Numbers', 20, 11, '&nbsp;بيا موسىٰ امسا پورته کړه او دوه ځله يې هغه ګټ پرې ووهلو او ډېرې زياتې اوبۀ ترې نه راووتلې او ټولو خلقو او ځناورو وڅښلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3993, 'Numbers 20:12', 'Numbers', 20, 12, '&nbsp;خو مالِک خُدائ موسىٰ او هارون ته وفرمائيل، ”تاسو په ما ايمان نۀ لرلو چې زما مقدس طاقت مو د بنى اِسرائيلو په مخکښې څرګند کړے وے، نو اوس تاسو به هغوئ هغه مُلک ته بونۀ ځئ چې ما يې د ورکولو وعده کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3994, 'Numbers 20:13', 'Numbers', 20, 13, '&nbsp;د دې ځائ نوم د مريبه اوبۀ شو، ځکه چې بنى اِسرائيلو د مالِک خُدائ خِلاف شکايت وکړو او هغۀ ورته هلته وښودل چې هغه مقدس دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3995, 'Numbers 20:14', 'Numbers', 20, 14, '&nbsp;موسىٰ د قادِس نه ادومى بادشاه له پېغام وړُونکى ولېږل. هغوئ ورته ووئيل، ”دا پېغام ستاسو د خپلوانو، د بنى اِسرائيلو د طرف نه دے. تاسو ته پته ده چې په مونږ کوم تکليفونه تېر شوى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3996, 'Numbers 20:15', 'Numbers', 20, 15, '&nbsp;چې زمونږ پلار نيکۀ څنګه مِصر ته لاړل، هلته مونږ ډېر وخت اوسېدلو. مِصريانو زمونږ د پلار نيکۀ او زمونږ سره بد سلوک کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3997, 'Numbers 20:16', 'Numbers', 20, 16, '&nbsp;او مونږ مالِک خُدائ ته فرياد وکړو. او هغۀ زمونږ فرياد واورېدو او يوه فرښته يې راولېږله، چې د مِصر نه يې راوويستلو. اوس مونږ ستاسو د علاقې سره نزدې په يو ښار قادِس کښې يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3998, 'Numbers 20:17', 'Numbers', 20, 17, '&nbsp;تاسو مِهربانى وکړئ او مونږ پرېږدئ چې ستاسو د مُلک نه تېر شُو. مونږ او زمونږ څاروى به د لارې نه يو خوا بل خوا نۀ اوړُو، نۀ به ستاسو پټو يا د انګورو باغونو ته ورننوځو او نۀ به ستاسو د کُوهو نه اوبۀ څښو. مونږ به په هغه لويه لاره روان يُو او ستاسو علاقې نه به ووځُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3999, 'Numbers 20:18', 'Numbers', 20, 18, '&nbsp;خو ادوميانو ورته ووئيل، ”تاسو د دې ځائ نه نۀ شئ تېرېدلے. کۀ تاسو داسې وکړل، مونږ به راووځُو او په تاسو به حمله وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(4000, 'Numbers 20:19', 'Numbers', 20, 19, '&nbsp;بنى اِسرائيلو ووئيل، ”مونږ په لويه لاره روان يُو او کۀ مونږ او زمونږ څاروو ستاسو اوبۀ وڅښلې، نو مونږ به د هغې پېسې درکړُو. مونږ صِرف ستاسو په مُلک کښې تېرېدل غواړُو نور هيڅ هم نه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');